def parse_embedded_evidence(payload: dict[str, Any]) -> dict[str, Any]:
    if payload.get("model") != MODEL:
        raise ValueError("payload model does not match")
    if payload.get("stream") is not True:
        raise ValueError("payload stream is not true")
    input_items = payload.get("input") or []
    if len(input_items) != 1 or input_items[0].get("role") != "user":
        raise ValueError("payload must contain exactly one user message")
    content = input_items[0].get("content") or []
    if len(content) != 1 or content[0].get("type") != "input_text":
        raise ValueError("payload must contain one input_text block")
    text = content[0].get("text") or ""
    marker = "EVIDENCE_JSON\n"
    if marker not in text:
        raise ValueError("EVIDENCE_JSON marker is missing")
    evidence_text = text.split(marker, 1)[1]
    try:
        return json.loads(evidence_text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"embedded evidence is not valid JSON: {exc}") from exc


def validate_final_payload(payload: dict[str, Any], evidence_path: Path) -> dict[str, Any]:
    errors: list[str] = []
    try:
        embedded = parse_embedded_evidence(payload)
    except ValueError as exc:
        embedded = None

from __future__ import annotations

from typing import Protocol


class RangeTransformer(Protocol):
    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        """Convert canonical range offsets into map tiles for one facing direction."""


class CanonicalSyntheticRangeTransformer:
    """Synthetic-only orientation rule; it makes no claim about Arknights' rule.

    Offsets are defined for RIGHT. RIGHT=(dx,dy), DOWN=(-dy,dx), LEFT=(-dx,-dy),
    and UP=(dy,-dx), with x increasing right and y increasing down.
    """

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported synthetic direction: {direction}")
        def rotate(dx: int, dy: int) -> tuple[int, int]:
            if direction == "RIGHT": return dx, dy
            if direction == "DOWN": return -dy, dx
            if direction == "LEFT": return -dx, -dy
            return dy, -dx
        return {(origin[0] + rotate(dx, dy)[0], origin[1] + rotate(dx, dy)[1]) for dx, dy in offsets}


class ApproximateRealRangeTransformer:
    """Real raw range cells in the fixture's bottom-left field coordinates."""

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported real direction: {direction}")
        def rotate(row: int, col: int) -> tuple[int, int]:
            if direction == "RIGHT": return col, row
            if direction == "DOWN": return row, -col
            if direction == "LEFT": return -col, -row
            return -row, col
        return {
            (origin[0] + rotate(row, col)[0], origin[1] + rotate(row, col)[1])
            for row, col in offsets
        }

